namespace generic.util.action;








public class SelectBeginningOfLineAction : TextAction {

	public static readonly KeyStroke KEY_STROKE = KeyStroke.getKeyStroke(KeyEvent.VK_HOME,
		InputEvent.SHIFT_DOWN_MASK);
	private static readonly string ACTION_NAME = "selection-begin-line";

	public SelectBeginningOfLineAction() : base(ACTION_NAME)
    {
	}

	private void error(Component component) {
		UIManager.getLookAndFeel().provideErrorFeedback(component);
	}

	/* @Override */
	public void actionPerformed(ActionEvent e) {
		JTextComponent component = getTextComponent(e);
		if (component == null) {
			return;
		}

		try {
			int dot = component.getCaretPosition();
			int startPosition = Utilities.getRowStart(component, dot);
			component.moveCaretPosition(startPosition);
		}
		catch (BadLocationException bl) {
			error(component);
		}
	}
}
